using Essco.Domain.Payroll;namespace Essco.Application.Payroll;
public interface IPayrollRepository{ValueTask<IReadOnlyCollection<PayrollRun>>ListAsync(PayrollFilter filter,CancellationToken token);ValueTask<PayrollRun?>GetAsync(int number,CancellationToken token);ValueTask<(bool Succeeded,int?Number,string?Error)>CreateAsync(int type,DateOnly from,DateOnly to,string comments,string user,CancellationToken token);ValueTask<(bool Succeeded,string?Error)>FinalizeAsync(int number,CancellationToken token);ValueTask<(bool Succeeded,string?Error)>CancelAsync(int number,CancellationToken token);}
public sealed class PayrollService(IPayrollRepository repository){public ValueTask<IReadOnlyCollection<PayrollRun>>ListAsync(PayrollFilter f,CancellationToken t)=>repository.ListAsync(f,t);public ValueTask<PayrollRun?>GetAsync(int n,CancellationToken t)=>repository.GetAsync(n,t);public async ValueTask<(bool Succeeded,int?Number,string?Error)>CreateAsync(int type,DateOnly from,DateOnly to,string comments,string user,CancellationToken t){if(from>to)return(false,null,"El rango de fechas es inválido.");if(string.IsNullOrWhiteSpace(user))return(false,null,"El usuario es obligatorio.");return await repository.CreateAsync(type,from,to,comments.Trim(),user,t);}public ValueTask<(bool Succeeded,string?Error)>FinalizeAsync(int n,CancellationToken t)=>repository.FinalizeAsync(n,t);public ValueTask<(bool Succeeded,string?Error)>CancelAsync(int n,CancellationToken t)=>repository.CancelAsync(n,t);}
